        </div>
        {RULES.map((r, i) => {
          const d = 34 + i * 22;
          const e = spring({frame: frame - d, fps, config: {damping: 200}});
          const bar = interpolate(frame, [d, d + 22], [0, 1], {...cl, easing: Easing.out(Easing.cubic)});
          const tick = interpolate(frame, [d + 14, d + 32], [0, 1], cl);
          return (
            <div key={r} style={{position: 'absolute', left: 120, top: 330 + i * 150, width: 1680, height: 120, display: 'flex', alignItems: 'center', gap: 36, boxSizing: 'border-box', padding: '0 40px', borderRadius: 24, background: C.panel, opacity: e, transform: `translateX(${interpolate(e, [0, 1], [-70, 0])}px)`}}>
